"""Management command to find and remove cross-source duplicate RegionEvents."""

from typing import Any

from django.core.management.base import BaseCommand

from trips.models import RegionCalendar
from trips.services.dedup_service import RegionEventDedupService


class Command(BaseCommand):
    help = "Find and optionally remove cross-source duplicate RegionEvents"

    def add_arguments(self, parser: Any) -> None:
        parser.add_argument(
            "--apply",
            action="store_true",
            help="Actually delete duplicates (default is dry-run)",
        )
        parser.add_argument(
            "--region",
            help="Filter to a specific region calendar by region name",
        )

    def handle(self, *args: Any, **options: Any) -> None:
        apply = options["apply"]
        region_filter = options.get("region")

        calendars = RegionCalendar.objects.select_related("region")
        if region_filter:
            calendars = calendars.filter(region__name__icontains=region_filter)

        if not calendars.exists():
            self.stdout.write("No matching region calendars found.")
            return

        total_pairs = 0

        for calendar in calendars:
            pairs = RegionEventDedupService.find_all_duplicates(calendar)
            if not pairs:
                self.stdout.write(f"{calendar.region.name}: no duplicates found")
                continue

            self.stdout.write(
                self.style.WARNING(
                    f"\n{calendar.region.name}: {len(pairs)} duplicate(s) found"
                )
            )

            for keep, remove in pairs:
                keep_source = self._source_label(keep)
                remove_source = self._source_label(remove)
                self.stdout.write(
                    f'  KEEP: [{keep_source}] "{keep.name}" '
                    f"({keep.start_datetime.date()})"
                )
                self.stdout.write(
                    f'  DEL:  [{remove_source}] "{remove.name}" '
                    f"({remove.start_datetime.date()})"
                )

                if apply:
                    remove.delete()
                    self.stdout.write(self.style.SUCCESS("  -> Deleted"))
                else:
                    self.stdout.write("  -> (dry-run, use --apply to delete)")

            total_pairs += len(pairs)

        mode = "Deleted" if apply else "Found"
        self.stdout.write(
            self.style.SUCCESS(f"\n{mode} {total_pairs} duplicate(s) total.")
        )

    @staticmethod
    def _source_label(event: Any) -> str:
        if event.rss_feed_source:
            return f"RSS: {event.rss_feed_source.name}"
        if event.event_source:
            return f"{event.event_source.get_source_type_display()}: {event.event_source.name}"
        return "Unknown"

