)
_CONCRETE_DATE_CUE_RE = re.compile(
    r"\b(?:"
    r"(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?"
    r"|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)"
    r"\s+\d{1,2}(?:st|nd|rd|th)?"
    r"|(?:\d{4}-\d{2}-\d{2})"
    r")\b",
    re.IGNORECASE,
)
_QUALITY_GATE_MARKER_ONLY_RE = re.compile(r"^#?\s*\(?\d+\)?[.)-]?$")
_QUALITY_GATE_CONTINUATION_RE = re.compile(
    r"^(?:or\s+\w|bowl\b|cup\b|half\b|half-|full\b|over\b|available from\b|am\b|pm\b)",
    re.IGNORECASE,
)
_QUALITY_GATE_CLIPPED_UNIT_RE = re.compile(
    r"^(?:oz|lb|lbs|inch|inches)\b",
    re.IGNORECASE,
)
_QUALITY_GATE_PERCENT_LOSS_RE = re.compile(r"^%\s*off\b", re.IGNORECASE)
_QUALITY_GATE_NUMERIC_PREFIX_RE = re.compile(
    r"^\s*\d+(?:\.\d+)?(?=(?:\s*(?:oz|lb|lbs|inch|inches|%)))",
    re.IGNORECASE,
)
_QUALITY_GATE_NUMERIC_UNIT_RE = re.compile(
    r"\b\d+(?:\.\d+)?\s*(?:oz|lb|lbs|inch|inches)\b",
    re.IGNORECASE,
)
_QUALITY_GATE_REPAIR_NONE = "NONE"
_QUALITY_GATE_REPAIR_SAFE_RAW = "SAFE_RAW"
_QUALITY_GATE_REPAIR_DISABLE_COLLAPSE = "DISABLE_COLLAPSE"
_QUALITY_GATE_REPAIR_STRIP_RECURRENCE = "STRIP_RECURRENCE"
_QUALITY_GATE_REPAIR_BLOCK = "BLOCK"
_WEEKDAY_TO_INDEX = {
    "monday": 0,
    "tuesday": 1,
    "wednesday": 2,
    "thursday": 3,
    "friday": 4,
    "saturday": 5,
    "sunday": 6,
}
_MEAL_PERIOD_PATTERNS: tuple[tuple[MealPeriod, tuple[str, ...]], ...] = (
    (MealPeriod.ALL_DAY, ("all day", "all-day")),
    (MealPeriod.BREAKFAST, ("breakfast",)),
    (MealPeriod.LUNCH, ("lunch",)),
    (MealPeriod.DINNER, ("dinner",)),
    (MealPeriod.BRUNCH, ("brunch",)),
