_GENERIC_ATTACHMENT_TITLE_RE = re.compile(
    r"^(?:img|dsc|pxl|mvimg|vid|photo|image)[-_ ]?\d+(?:\.[a-z0-9]+)?$",
    re.IGNORECASE,
)
_FOOD_TITLE_CONFIDENT_PHRASES = (
    "special",
    "specials",
    "menu",
