    reference_date: date = date(2026, 3, 27),
    food_summary_mode: str = "normalized",
    collapse_food: bool = True,
) -> AnalyzedPackage:
    return _build_analyzed_package(
        package=package,
        raw=raw,
        reference_date=reference_date,
        notes_prefix="test",
        provider="test",
        raw_output="{}",
        model="test-model",
        food_summary_mode=food_summary_mode,
        collapse_food=collapse_food,
    )


def _broken_food_analyzed(
    *,
    package: SlackMessagePackage,
    raw: dict,
    summary: str,
    recurrence_pattern: str | None = None,
) -> AnalyzedPackage:
    analyzed = _build_food_analyzed(
        package=package,
        raw=raw,
        food_summary_mode="safe_raw",
        collapse_food=False,
    )
    item = analyzed.items[0]
    overridden = replace(
        item,
        summary=summary,
        recurrence_pattern=recurrence_pattern or item.recurrence_pattern,
    )
    return AnalyzedPackage(
        package=package,
        image_classifications=analyzed.image_classifications,
        items=[overridden],
        debug={
            "provider": "test",
            "model": "test-model",
            "raw_output": "{}",
            "parsed_output": raw,
        },
    )


