def test_redundant_analyzer_falls_back_to_gemini_when_openai_fails():
    package = _package(
        text="Taco Tuesday every Tuesday through December 31 at Paco's Tacos.",
        attachments=[SlackFile(file_id="F8", name="taco.jpg", title="Taco Tuesday")],
    )

    class BrokenAnalyzer:
        def analyze_package(self, package):
            raise RuntimeError("openai unavailable")

    class PassingAnalyzer:
        def __init__(self):
            self.calls = 0

        def analyze_package(self, package):
            self.calls += 1
            return HeuristicAnalyzer(reference_date=date(2026, 3, 9)).analyze_package(
                package
            )

    fallback = PassingAnalyzer()
    analyzer = RedundantAnalyzer([BrokenAnalyzer(), fallback])

    analyzed = analyzer.analyze_package(package)

    assert fallback.calls == 1
    assert analyzed.items[0].title == "Taco Tuesday"


