"""Nightly reconciliation of published specials against the public feed.

Cross-checks three sources of truth for a region day:
- the local state DB (what we analyzed and uploaded, with per-event backend
  receipts from the ingest response),
- the public specials JSONL feed (what actually renders),
- the reconcile card history (which cards rendered on previous days).

Detections:
- ``missing_item``: a successfully uploaded FOOD item that should occur
  today has no card in the feed (matched by backend event id).
- ``zombie_card``: the same card has rendered for more than
  ``ZOMBIE_CONSECUTIVE_DAYS`` consecutive days.
- ``duplicate_venue_day``: two cards for the same venue today with similar
  titles.
- ``weekday_mismatch``: a card whose title names a single weekday that is
  not today's weekday.

The matching logic is pure (no network); the CLI wrapper fetches the feed.
"""

from __future__ import annotations

import json
import logging
import urllib.request
from dataclasses import asdict, dataclass
from datetime import date, timedelta
from difflib import SequenceMatcher
from typing import Any

from slack_region_ingest.analyzer import (
    _single_weekday_from_text,
    _slug_token,
)
from slack_region_ingest.models import ContentType, NormalizedItem, StoredPackage

_log = logging.getLogger("scrapers.reconcile")

#: A card rendering this many consecutive days is suspicious.
ZOMBIE_CONSECUTIVE_DAYS = 10

#: Fallback horizon for recurring items with no recurrence_end_date,
#: matching the backend's scraped-recurrence horizon.
RECURRENCE_HORIZON_DAYS = 14

_DUPLICATE_TITLE_SIMILARITY = 0.82


@dataclass
class ReconcileFinding:
    kind: str
    detail: str
    event_id: int | None = None
    external_id: str = ""


def item_occurs_on(item: NormalizedItem, day: date) -> bool:
    """Whether a normalized item is expected to render on ``day``."""
    if item.start_date is None:
        return False
    if item.recurrence_pattern == "NONE":
        end = item.end_date or item.start_date
        return item.start_date <= day <= end
    if day < item.start_date:
        return False
    recurrence_end = item.recurrence_end_date or (
        item.start_date + timedelta(days=RECURRENCE_HORIZON_DAYS)
    )
    if day > recurrence_end:
        return False
    if item.recurrence_pattern == "DAILY":
        return True
    if item.recurrence_pattern == "WEEKLY":
        days = {
            int(token)
            for token in (item.recurrence_days or "").split(",")
            if token.strip().lstrip("-").isdigit()
        }
        if not days:
            days = {item.start_date.weekday()}
        return day.weekday() in days
    return False


def collect_expected_events(
    packages: list[StoredPackage], *, day: date
) -> dict[int, str]:
    """Map backend event ids to labels for items expected to render today.

    Only items with a per-event receipt (``results`` in the stored backend
    metadata, keyed by external_id) can be matched exactly; items uploaded
    before receipts existed are skipped.
    """
    expected: dict[int, str] = {}
    for package in packages:
        if package.backend_status != "success":
            continue
        metadata = package.backend_metadata or {}
        receipts = {
            str(entry.get("external_id") or ""): entry
            for entry in (metadata.get("results") or [])
            if isinstance(entry, dict)
        }
        if not receipts:
            continue
        for item in package.analyzed.items:
            if item.content_type != ContentType.FOOD:
                continue
            receipt = receipts.get(item.external_id)
            if not receipt or receipt.get("action") in ("error", None):
                continue
            event_id = receipt.get("event_id")
            if not isinstance(event_id, int):
                continue
            if item_occurs_on(item, day):
                expected[event_id] = f"{item.title} ({item.external_id})"
    return expected


def reconcile_feed(
    *,
    expected_events: dict[int, str],
    feed_entries: list[dict[str, Any]],
    day: date,
    card_streaks: dict[int, int] | None = None,
) -> list[ReconcileFinding]:
    findings: list[ReconcileFinding] = []
    feed_ids = {
        entry.get("id") for entry in feed_entries if isinstance(entry.get("id"), int)
    }

    for event_id, label in sorted(expected_events.items()):
        if event_id not in feed_ids:
            findings.append(
                ReconcileFinding(
                    kind="missing_item",
                    detail=(
                        f"Uploaded item {label} should render on "
                        f"{day.isoformat()} but has no card in the feed"
                    ),
                    event_id=event_id,
                )
            )

    by_venue: dict[str, list[dict[str, Any]]] = {}
    for entry in feed_entries:
        venue_token = _slug_token(str(entry.get("venue") or ""))
        if venue_token:
            by_venue.setdefault(venue_token, []).append(entry)
    for venue_token, entries in sorted(by_venue.items()):
        if len(entries) < 2:
            continue
        for index, first in enumerate(entries):
            for second in entries[index + 1 :]:
                similarity = SequenceMatcher(
                    None,
                    str(first.get("title") or "").lower(),
                    str(second.get("title") or "").lower(),
                ).ratio()
                if similarity >= _DUPLICATE_TITLE_SIMILARITY:
                    findings.append(
                        ReconcileFinding(
                            kind="duplicate_venue_day",
                            detail=(
                                f"Venue '{venue_token}' has duplicate cards on "
                                f"{day.isoformat()}: "
                                f"{first.get('id')} '{first.get('title')}' and "
                                f"{second.get('id')} '{second.get('title')}'"
                            ),
                            event_id=second.get("id"),
                        )
                    )

    for entry in feed_entries:
        title_day = _single_weekday_from_text(str(entry.get("title") or ""))
        if title_day is not None and title_day != day.weekday():
            findings.append(
                ReconcileFinding(
                    kind="weekday_mismatch",
                    detail=(
                        f"Card {entry.get('id')} '{entry.get('title')}' names a "
                        f"weekday but rendered on {day.strftime('%A')} "
                        f"{day.isoformat()}"
                    ),
                    event_id=entry.get("id"),
                )
            )

    for event_id, streak in sorted((card_streaks or {}).items()):
        if streak <= ZOMBIE_CONSECUTIVE_DAYS:
            continue
        titles = [
            str(entry.get("title") or "")
            for entry in feed_entries
            if entry.get("id") == event_id
        ]
        findings.append(
            ReconcileFinding(
                kind="zombie_card",
                detail=(
                    f"Card {event_id} '{titles[0] if titles else '?'}' has "
                    f"rendered {streak} consecutive days"
                ),
                event_id=event_id,
            )
        )

    return findings


def fetch_specials_feed(url: str, *, timeout: int = 30) -> list[dict[str, Any]]:
    """Fetch the public specials JSONL feed and parse one entry per line."""
    request = urllib.request.Request(  # noqa: S310 - operator-configured URL
        url, headers={"User-Agent": "slack-region-ingest-reconcile/1.0"}
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:  # noqa: S310
        body = response.read().decode("utf-8")
    entries: list[dict[str, Any]] = []
    for line in body.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            entry = json.loads(line)
        except json.JSONDecodeError:
            _log.warning("Skipping malformed feed line: %.120s", line)
            continue
        if isinstance(entry, dict):
            entries.append(entry)
    return entries


def run_reconcile(
    *,
    state,
    region_key: str,
    timezone: str,
    feed_entries: list[dict[str, Any]],
    today: date,
    lookback_days: int = 7,
) -> dict[str, Any]:
    """Run all reconcile checks for ``today`` and return a JSON-able report."""
    packages: list[StoredPackage] = []
    for offset in range(lookback_days + 1):
        packages.extend(
            state.list_packages_for_local_day(
                region_key,
                day=today - timedelta(days=offset),
                timezone=timezone,
            )
        )

    expected_events = collect_expected_events(packages, day=today)
    feed_ids = [
        entry["id"] for entry in feed_entries if isinstance(entry.get("id"), int)
    ]
    card_streaks = state.record_reconcile_cards(region_key, feed_ids, day=today)
    findings = reconcile_feed(
        expected_events=expected_events,
        feed_entries=feed_entries,
        day=today,
        card_streaks=card_streaks,
    )
    return {
        "region": region_key,
        "day": today.isoformat(),
        "packages_checked": len(packages),
        "expected_event_count": len(expected_events),
        "feed_card_count": len(feed_entries),
        "findings": [asdict(finding) for finding in findings],
    }


def format_findings_summary(report: dict[str, Any]) -> str:
    findings = report.get("findings") or []
    if not findings:
        return (
            f"Specials reconcile {report.get('day')}: all good — "
            f"{report.get('expected_event_count')} expected items, "
            f"{report.get('feed_card_count')} cards."
        )
    lines = [
        f"Specials reconcile {report.get('day')}: {len(findings)} finding(s) "
        f"({report.get('expected_event_count')} expected items, "
        f"{report.get('feed_card_count')} cards):"
    ]
    lines.extend(f"- [{f['kind']}] {f['detail']}" for f in findings)
    return "\n".join(lines)

