            if entry.get("id") == event_id
        ]
        findings.append(
            ReconcileFinding(
                kind="zombie_card",
                detail=(
                    f"Card {event_id} '{titles[0] if titles else '?'}' has "
                    f"rendered {streak} consecutive days"
                ),
                event_id=event_id,
            )
        )

    return findings


def fetch_specials_feed(url: str, *, timeout: int = 30) -> list[dict[str, Any]]:
    """Fetch the public specials JSONL feed and parse one entry per line."""
    request = urllib.request.Request(  # noqa: S310 - operator-configured URL
        url, headers={"User-Agent": "slack-region-ingest-reconcile/1.0"}
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:  # noqa: S310
        body = response.read().decode("utf-8")
    entries: list[dict[str, Any]] = []
    for line in body.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            entry = json.loads(line)
        except json.JSONDecodeError:
            _log.warning("Skipping malformed feed line: %.120s", line)
            continue
        if isinstance(entry, dict):
            entries.append(entry)
    return entries


def run_reconcile(
    *,
    state,
    region_key: str,
    timezone: str,
    feed_entries: list[dict[str, Any]],
    today: date,
    lookback_days: int = 7,
) -> dict[str, Any]:
    """Run all reconcile checks for ``today`` and return a JSON-able report."""
    packages: list[StoredPackage] = []
    for offset in range(lookback_days + 1):
        packages.extend(
            state.list_packages_for_local_day(
                region_key,
                day=today - timedelta(days=offset),
                timezone=timezone,
            )
        )

    expected_events = collect_expected_events(packages, day=today)
    feed_ids = [
        entry["id"] for entry in feed_entries if isinstance(entry.get("id"), int)
    ]
    card_streaks = state.record_reconcile_cards(region_key, feed_ids, day=today)
    findings = reconcile_feed(
        expected_events=expected_events,
        feed_entries=feed_entries,
        day=today,
        card_streaks=card_streaks,
    )
    return {
        "region": region_key,
        "day": today.isoformat(),
        "packages_checked": len(packages),
        "expected_event_count": len(expected_events),
        "feed_card_count": len(feed_entries),
        "findings": [asdict(finding) for finding in findings],
    }


def format_findings_summary(report: dict[str, Any]) -> str:
    findings = report.get("findings") or []
    if not findings:
        return (
            f"Specials reconcile {report.get('day')}: all good — "
            f"{report.get('expected_event_count')} expected items, "
            f"{report.get('feed_card_count')} cards."
        )
    lines = [
        f"Specials reconcile {report.get('day')}: {len(findings)} finding(s) "
        f"({report.get('expected_event_count')} expected items, "
        f"{report.get('feed_card_count')} cards):"
    ]
    lines.extend(f"- [{f['kind']}] {f['detail']}" for f in findings)
    return "\n".join(lines)

