from __future__ import annotations

from datetime import date, datetime
from zoneinfo import ZoneInfo

from slack_region_ingest.models import (
    AnalyzedPackage,
    ContentType,
    NormalizedItem,
    SlackMessagePackage,
    TimingBucket,
)
from slack_region_ingest.reconcile import (
    ReconcileFinding,
    collect_expected_events,
    format_findings_summary,
    item_occurs_on,
    reconcile_feed,
    run_reconcile,
)
from slack_region_ingest.state import SqliteStateStore

TODAY = date(2026, 6, 10)  # a Wednesday
EASTERN = "America/New_York"


def _item(**overrides) -> NormalizedItem:
    values = dict(
        package_key="C123:1749556800.000100",
        external_id="C123:1749556800.000100:F1:henrys:2026-06-10",
        title="Henry's Specials",
        summary="Wings $12",
        content_type=ContentType.FOOD,
        timing=TimingBucket.THIS_WEEK,
        start_date=TODAY,
        end_date=TODAY,
        location="Henry's Restaurant",
    )
    values.update(overrides)
    return NormalizedItem(**values)


class TestItemOccursOn:
    def test_none_item_on_its_day(self) -> None:
        assert item_occurs_on(_item(), TODAY) is True
        assert item_occurs_on(_item(), date(2026, 6, 11)) is False

    def test_daily_within_range(self) -> None:
        item = _item(
            recurrence_pattern="DAILY",
            recurrence_end_date=date(2026, 6, 12),
            start_date=date(2026, 6, 8),
            end_date=date(2026, 6, 8),
        )
        assert item_occurs_on(item, TODAY) is True
        assert item_occurs_on(item, date(2026, 6, 13)) is False

    def test_daily_without_end_uses_horizon(self) -> None:
        item = _item(
            recurrence_pattern="DAILY",
            recurrence_end_date=None,
            start_date=date(2026, 5, 1),
            end_date=date(2026, 5, 1),
        )
        # 14-day horizon from May 1 ends well before June 10.
        assert item_occurs_on(item, TODAY) is False
        assert item_occurs_on(item, date(2026, 5, 10)) is True

    def test_weekly_matches_weekday(self) -> None:
        item = _item(
            recurrence_pattern="WEEKLY",
            recurrence_days="2",  # Wednesday
            recurrence_end_date=date(2026, 6, 30),
            start_date=date(2026, 6, 3),
            end_date=date(2026, 6, 3),
        )
        assert item_occurs_on(item, TODAY) is True
        assert item_occurs_on(item, date(2026, 6, 11)) is False


class TestReconcileFeed:
    def test_missing_item_flagged(self) -> None:
        findings = reconcile_feed(
            expected_events={42: "Henry's Specials (ext-1)"},
            feed_entries=[],
            day=TODAY,
        )
        assert [f.kind for f in findings] == ["missing_item"]
        assert findings[0].event_id == 42

    def test_present_item_not_flagged(self) -> None:
        findings = reconcile_feed(
            expected_events={42: "Henry's Specials (ext-1)"},
            feed_entries=[{"id": 42, "title": "Specials", "venue": "Henry's"}],
            day=TODAY,
        )
        assert findings == []

    def test_duplicate_venue_day_flagged(self) -> None:
        findings = reconcile_feed(
            expected_events={},
            feed_entries=[
                {"id": 1, "title": "Henry's Specials", "venue": "Henry's Restaurant"},
                {"id": 2, "title": "Henry's Specials!", "venue": "Henry's Restaurant"},
            ],
            day=TODAY,
        )
        assert [f.kind for f in findings] == ["duplicate_venue_day"]
        assert findings[0].event_id == 2

    def test_distinct_titles_same_venue_not_flagged(self) -> None:
        findings = reconcile_feed(
